class Vokabeltrainer:
    def __init__(self, vokabeln):
        self.vokabeln = vokabeln
        self.fehler = 0

    def pruefe(self, deutsch, antwort):
        if antwort.lower() == self.vokabeln[deutsch].lower():
            return True
        self.fehler = self.fehler + 1
        return False

